import{_ as a,o,c as s,a4 as t}from"./chunks/framework.DA9C4Pbl.js";const k=JSON.parse('{"title":"Upgrading to CLI 4.0","description":"","frontmatter":{"title":"Upgrading to CLI 4.0","visibility":"public","audience":"operator","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/operating/upgrading-to-4.md","filePath":"guides/operating/upgrading-to-4.md"}'),d={name:"guides/operating/upgrading-to-4.md"};function r(i,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="upgrading-to-cli-4-0" tabindex="-1">Upgrading to CLI 4.0 <a class="header-anchor" href="#upgrading-to-cli-4-0" aria-label="Permalink to “Upgrading to CLI 4.0”">​</a></h1><p>Version 4.0 of the <code>arcsecond</code> tool changes how an installation is <em>operated</em>. The installation itself — your folder, <code>.env</code>, <code>docker-compose.yml</code>, the database, the data — needs no change and is not touched by the upgrade.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arcsecond</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # once, in the Arcsecond folder: records its location, adds new .env keys</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # brings the installation to the latest release</span></span></code></pre></div><h2 id="no-more-docker-commands" tabindex="-1">No more <code>docker</code> commands <a class="header-anchor" href="#no-more-docker-commands" aria-label="Permalink to “No more docker commands”">​</a></h2><p>Everything these pages used to ask for as a <code>docker compose …</code> line has an <code>arcsecond</code> command:</p><table tabindex="0"><thead><tr><th>Before 4.0</th><th>Since 4.0</th></tr></thead><tbody><tr><td><code>docker compose up -d</code></td><td><code>arcsecond start</code> — waits for the backend, prints the address</td></tr><tr><td><code>docker compose stop</code></td><td><code>arcsecond stop</code></td></tr><tr><td><code>docker compose up -d --force-recreate backend worker beat</code></td><td><code>arcsecond restart backend worker beat</code> (or just <code>arcsecond restart</code>)</td></tr><tr><td><code>docker compose ps</code>, <code>docker ps</code></td><td><code>arcsecond status</code></td></tr><tr><td><code>docker compose logs --tail 50 backend</code>, <code>docker logs -f arcsecond-alerts</code></td><td><code>arcsecond logs backend --tail 50</code>, <code>arcsecond logs alerts -f</code></td></tr><tr><td><code>arcsecond setup</code> + <code>docker compose pull</code> + <code>docker compose up -d</code></td><td><code>arcsecond update</code></td></tr><tr><td><code>docker compose up -d alerts</code></td><td><code>arcsecond restart alerts</code></td></tr><tr><td><code>echo &lt;PAT&gt; | docker login ghcr.io …</code></td><td><code>arcsecond token set</code> (and <code>arcsecond setup</code> asks)</td></tr></tbody></table><p>These commands find the installation in the current folder, or in the folder <code>arcsecond setup</code> last ran in — so they work from a PowerShell opened anywhere — or where <code>--dir</code> points. <code>arcsecond start</code> also explains the failures the <a href="/guides/operating/troubleshooting">Troubleshooting</a> page used to: a port already taken, a user not in the <code>docker</code> group, Docker Desktop not running.</p><p>Since 4.2 there is no <code>docker</code> command left to type at all: <code>arcsecond setup</code> asks for the access token Arcsecond gave your observatory, and <code>arcsecond token set</code> enters it again.</p><h2 id="the-server-is-a-pointer-not-an-option" tabindex="-1">The server is a pointer, not an option <a class="header-anchor" href="#the-server-is-a-pointer-not-an-option" aria-label="Permalink to “The server is a pointer, not an option”">​</a></h2><p><code>--api &lt;name&gt;</code> is gone from every command. The CLI points at one server, and every command follows that pointer:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # list the servers, * marks the current one</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # every command now talks to your installation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # …and back</span></span></code></pre></div><p><code>arcsecond setup</code> registers <code>local</code> for you. A server registered the old way (<code>arcsecond api &lt;name&gt; &lt;address&gt;</code>) is still there and still registers; <code>arcsecond api add</code> is the new spelling. For scripts, <code>ARCSECOND_API=&lt;name&gt;</code> in the environment selects a server for that process alone.</p><p>In Python, <code>ArcsecondConfig()</code> with no name follows the pointer too; <code>ArcsecondConfig(api_name=&quot;local&quot;)</code> behaves as before.</p><h2 id="renamed-and-removed" tabindex="-1">Renamed and removed <a class="header-anchor" href="#renamed-and-removed" aria-label="Permalink to “Renamed and removed”">​</a></h2><ul><li><code>arcsecond upload-data</code> is <code>arcsecond upload</code>. The old name still works, hidden.</li><li><code>arcsecond me</code> is gone: <code>arcsecond login</code> tells you who you are logged in as, and where.</li><li><code>arcsecond netcam</code> is gone; a network camera is a webcam (<code>arcsecond webcam add rtsp://…</code>).</li><li>Errors are sentences: a command that cannot do what it was asked says why and exits, instead of printing a traceback.</li></ul><h2 id="the-live-image-proxy-comes-back-after-a-reboot" tabindex="-1">The live-image proxy comes back after a reboot <a class="header-anchor" href="#the-live-image-proxy-comes-back-after-a-reboot" aria-label="Permalink to “The live-image proxy comes back after a reboot”">​</a></h2><p>A proxy started with <code>arcsecond proxy start</code> now registers itself to start again when you log in, and <code>arcsecond proxy stop</code> cancels that. A proxy that was running when the machine went down comes back; one you stopped stays stopped. <code>arcsecond proxy start --no-autostart</code> opts out. See <a href="/guides/operating/live-image-proxy">Live-Image Proxy</a>.</p><h2 id="other-computers-on-the-network" tabindex="-1">Other computers on the network <a class="header-anchor" href="#other-computers-on-the-network" aria-label="Permalink to “Other computers on the network”">​</a></h2><p><code>arcsecond setup --lan-host 192.168.1.42</code> writes the address other computers reach the installation at, which the backend needs for the links in invitation and password-reset emails. Editing <code>.env</code> by hand still works. See <a href="/start/network">Access from Other Computers</a>.</p>`,19)])])}const g=a(d,[["render",r]]);export{k as __pageData,g as default};
